<!--
 * 社交客户端配置管理页面 — 管理社交登录客户端配置
 *
 * @path apps\userinfo-web\src\views\social-client\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 社交客户端配置管理（列表页）
 * <p>社交登录客户端配置的列表页，消费后端契约 SocialClientConfigController
 * （src/api/socialClientConfig.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询配置列表，支持创建/编辑/启用禁用/删除等操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYdModal } from '@ydsz/common-ui';

import { YdBadge, YdButton, YdForm, YdFormItem, YdInput, YdNumberFieldInput, YdSelectItem, YdRadioGroupItem, YdRadioGroup, YdSelect } from '@ydsz-core/ydsz-ui';
import { computed, h, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@ydsz-core/shared/utils';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { create, deleteApi, page, update } from '#/api/socialClientConfig';
import type { SocialClientDTO, SocialClientVO } from '#/api/models';

defineOptions({ name: 'SocialClientManagement' });

const logger = createLogger('userinfo-social-client');
const { t } = useI18n();

/** 平台类型选项 */
const PLATFORM_OPTIONS = [
  { label: 'GitHub', value: 'GITHUB' },
  { label: 'Google', value: 'GOOGLE' },
  { label: '微信', value: 'WECHAT' },
  { label: 'Apple', value: 'APPLE' },
  { label: '钉钉', value: 'DINGTALK' },
  { label: '企业微信', value: 'ENTERPRISE_WECHAT' },
  { label: '飞书', value: 'FEISHU' },
];

/** 平台颜色映射 */
const platformColorMap: Record<string, string> = {
  GITHUB: '',
  GOOGLE: 'success',
  WECHAT: 'success',
  APPLE: 'info',
  DINGTALK: 'warning',
  ENTERPRISE_WECHAT: 'success',
  FEISHU: 'primary',
};

/** 状态判断 */
function isEnabled(status?: string): boolean {
  return status === 'ENABLED';
}

/** 获取平台标签类型 */
function getPlatformTagType(platform?: string): string {
  return platformColorMap[platform ?? ''] || 'info';
}

// ========== VxeTable 配置 ==========
const gridOptions: VxeTableGridOptions<SocialClientVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    {
      field: 'platform',
      title: '平台标识',
      width: 120,
      slots: {
        default: ({ row }) =>
          h(
            YdBadge,
            { variant: getPlatformTagType(row.platform) === 'primary' ? 'default' : getPlatformTagType(row.platform) === 'warning' ? 'outline' : 'secondary', class: 'text-xs' },
            () => row.platform ?? '-',
          ),
      },
    },
    { field: 'platformName', title: '平台名称', width: 120 },
    { field: 'appId', title: 'App ID', width: 160 },
    { field: 'scope', title: '授权范围', width: 140 },
    { field: 'redirectUri', title: '回调地址', minWidth: 200 },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            YdBadge,
            { variant: enable ? 'default' : 'destructive', class: enable ? 'bg-green-500 text-white hover:bg-green-600' : 'text-xs' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 240,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1 flex-wrap' }, [
            h(
              YdButton,
              { size: 'sm', variant: 'link', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              YdButton,
              {
                size: 'sm',
                variant: 'link',
                class: isEnabled(row.status) ? 'border-yellow-500 text-yellow-600 dark:text-yellow-400' : 'border-green-500 text-green-600 dark:text-green-400',
                onClick: () => handleToggleStatus(row),
              },
              () => (isEnabled(row.status) ? '禁用' : '启用'),
            ),
            h(
              YdButton,
              { size: 'sm', variant: 'link', class: 'text-destructive', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({
          query: {
            status: formValues?.status || undefined,
            platformName: formValues?.platformName || undefined,
            platform: formValues?.platform || undefined,
          },
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'YdInput',
        componentProps: { placeholder: '平台名称' },
        fieldName: 'platformName',
        label: '平台名称',
      },
      {
        component: 'YdSelectBase',
        componentProps: {
          placeholder: '平台',
          options: PLATFORM_OPTIONS,
        },
        fieldName: 'platform',
        label: '平台标识',
      },
      {
        component: 'YdSelectBase',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: '已启用', value: 'ENABLED' },
            { label: '已停用', value: 'DISABLED' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const formRef = ref();
const isEdit = ref(false);

interface SocialClientFormState {
  id: string;
  platform: string;
  platformName: string;
  appId: string;
  appSecret: string;
  scope: string;
  redirectUri: string;
  status: string;
  sortOrder: number;
  remark: string;
}

const formData = reactive<SocialClientFormState>({
  id: '',
  platform: '',
  platformName: '',
  appId: '',
  appSecret: '',
  scope: '',
  redirectUri: '',
  status: 'ENABLED',
  sortOrder: 0,
  remark: '',
});

const rules = {
  platform: [{ required: true, message: '请选择平台', trigger: 'change' }],
  platformName: [{ required: true, message: '请输入平台名称', trigger: 'blur' }],
  appId: [{ required: true, message: '请输入 App ID', trigger: 'blur' }],
  redirectUri: [{ required: true, message: '请输入回调地址', trigger: 'blur' }],
};

const [Modal, modalApi] = useYdModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: SocialClientVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        id: data.record.id ?? '',
        platform: data.record.platform ?? '',
        platformName: data.record.platformName ?? '',
        appId: data.record.appId ?? '',
        appSecret: '',
        scope: data.record.scope ?? '',
        redirectUri: data.record.redirectUri ?? '',
        status: data.record.status ?? 'ENABLED',
        sortOrder: data.record.sortOrder ?? 0,
        remark: data.record.remark ?? '',
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        id: '',
        platform: '',
        platformName: '',
        appId: '',
        appSecret: '',
        scope: '',
        redirectUri: '',
        status: 'ENABLED',
        sortOrder: 0,
        remark: '',
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch (error) {
      logger.warn('表单校验失败: {}', error);
      return;
    }
    modalApi.lock();
    try {
      const payload: SocialClientDTO = {
        id: formData.id || undefined,
        platform: formData.platform,
        platformName: formData.platformName,
        appId: formData.appId,
        appSecret: formData.appSecret || undefined,
        scope: formData.scope,
        redirectUri: formData.redirectUri,
        status: formData.status,
        sortOrder: formData.sortOrder,
        remark: formData.remark,
      };
      if (isEdit.value) {
        await update({ platform: formData.platform }, payload);
        showToast.success('更新成功');
      } else {
        await create(payload);
        showToast.success('创建成功');
      }
      modalApi.close();
      gridApi.query();
    } catch (error) {
      logger.warn('保存社交客户端配置失败: {}', error);
    } finally {
      modalApi.unlock();
    }
  },
});

const modalTitle = computed(() => (isEdit.value ? '编辑社交客户端配置' : '新增社交客户端配置'));

function handleAdd() {
  modalApi.setData({});
  modalApi.open();
}

function handleEdit(row: SocialClientVO) {
  modalApi.setData({ record: row });
  modalApi.open();
}

async function handleToggleStatus(row: SocialClientVO) {
  if (!row.platform) return;
  const newStatus = isEnabled(row.status) ? 'DISABLED' : 'ENABLED';
  try {
    await YdConfirm(
      `确认${isEnabled(row.status) ? '禁用' : '启用'}平台 "${row.platformName ?? row.platform}"？`,
      '确认操作',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await update({ platform: row.platform }, {
      id: row.id,
      platform: row.platform,
      platformName: row.platformName,
      appId: row.appId,
      scope: row.scope,
      redirectUri: row.redirectUri,
      status: newStatus,
      sortOrder: row.sortOrder,
      remark: row.remark,
    });
    showToast.success('操作成功');
    gridApi.query();
  } catch (error) {
    logger.warn('切换社交客户端状态失败: {}', error);
  }
}

async function handleDelete(row: SocialClientVO) {
  if (!row.platform) return;
  try {
    await YdConfirm(
      `确认删除平台 "${row.platformName ?? row.platform}" 配置？此操作不可恢复。`,
      '确认删除',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await deleteApi({ platform: row.platform });
    showToast.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除社交客户端配置失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="社交客户端配置管理">
      <template #toolbar-tools>
        <YdButton variant="default" @click="handleAdd">新增配置</YdButton>
      </template>
    </Grid>

    <!-- 创建/编辑弹窗 -->
    <Modal :title="modalTitle">
      <YdForm
        ref="formRef"
        :model="formData"
        :rules="rules"
        label-width="110px"
        label-position="right"
      >
        <YdFormItem label="平台" prop="platform">
          <YdSelect v-model="formData.platform" placeholder="请选择平台" :disabled="isEdit" class="w-full">
            <YdSelectItem
              v-for="opt in PLATFORM_OPTIONS"
              :key="opt.value"
              :label="opt.label"
              :value="opt.value"
            />
          </YdSelect>
        </YdFormItem>
        <YdFormItem label="平台名称" prop="platformName">
          <YdInput v-model="formData.platformName" placeholder="如 GitHub 登录" />
        </YdFormItem>
        <YdFormItem label="App ID" prop="appId">
          <YdInput v-model="formData.appId" placeholder="应用 ID / Client ID" />
        </YdFormItem>
        <YdFormItem label="App Secret">
          <YdInput
            v-model="formData.appSecret"
            type="password"
            show-password
            :placeholder="isEdit ? '留空则不修改' : '请输入应用密钥'"
          />
        </YdFormItem>
        <YdFormItem label="授权范围" prop="scope">
          <YdInput v-model="formData.scope" placeholder="如 user:email,openid" />
        </YdFormItem>
        <YdFormItem label="回调地址" prop="redirectUri">
          <YdInput v-model="formData.redirectUri" placeholder="如 https://example.com/auth/callback" />
        </YdFormItem>
        <YdFormItem label="状态">
          <YdRadioGroup v-model="formData.status">
            <YdRadioGroupItem value="ENABLED">已启用</YdRadioGroupItem>
            <YdRadioGroupItem value="DISABLED">已停用</YdRadioGroupItem>
          </YdRadioGroup>
        </YdFormItem>
        <YdFormItem label="排序">
          <YdNumberFieldInput v-model="formData.sortOrder" :min="0" :max="999" />
        </YdFormItem>
        <YdFormItem label="备注">
          <YdInput v-model="formData.remark" type="textarea" :rows="2" placeholder="备注说明" />
        </YdFormItem>
      </YdForm>
    </Modal>
  </Page>
</template>
